solutions.naive:
class Solution:
    def totalHammingDistance(self, nums: list[int]) -> int:
        ans = 0
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                ans += (nums[i] ^ nums[j]).bit_count()
        return ans

solutions.better:
class Solution:
    def totalHammingDistance(self, nums: list[int]) -> int:
        width = max(1, max(nums).bit_length())
        ans = 0
        for bit in range(width):
            ones = 0
            for x in nums:
                ones += (x >> bit) & 1
            ans += ones * (len(nums) - ones)
        return ans

