class Solution:
    def totalHammingDistance(self, nums: list[int]) -> int:
        n = len(nums)
        ans = 0
        for bit in range(30):
            ones = sum((x >> bit) & 1 for x in nums)
            ans += ones * (n - ones)
        return ans

